"use client";

import React, { useRef, Suspense, useMemo, useState, useEffect } from "react";
import { Canvas, useFrame, useLoader } from "@react-three/fiber";
import { OrbitControls } from "@react-three/drei";
import * as THREE from "three";
import { cn } from "../lib/utils";

export interface Globe2Props {
  /** Visual theme mode: 'monochrome' (black & white platinum) or 'default' (midnight sapphire & steel) */
  mode?: "monochrome" | "default";
  /** URL to earth bump map texture (elevation heightmap) */
  bumpMapUrl?: string;
  /** URL to earth water/land specular mask texture */
  waterMapUrl?: string;
  /** Enable automatic idle spin */
  autoRotate?: boolean;
  /** Speed of auto rotation per frame */
  rotationSpeed?: number;
  /** Allow mouse drag orbit controls */
  interactive?: boolean;
  /** Allow scroll wheel / pinch zoom */
  enableZoom?: boolean;
  /** Minimum camera zoom distance */
  minDistance?: number;
  /** Maximum camera zoom distance */
  maxDistance?: number;
  /** Camera field of view */
  fov?: number;
  /** Container CSS class name */
  className?: string;
  /** Container CSS inline styles */
  style?: React.CSSProperties;
}

// ── Curated Palettes ────────────────────────────────────────────────────────
const THEMES = {
  monochrome: {
    oceanColor: "#05070c",       // Deep velvet obsidian carbon black
    landColor: "#f8fafc",        // Luminous crisp silvery-white platinum continents
    atmosphereColor: "#e2e8f0",  // Delicate pearl-silver atmospheric glow
    ambientColor: "#1e293b",     // Low-level ambient to preserve deep blacks
    fillLightColor: "#475569",   // Soft secondary fill
  },
  default: {
    oceanColor: "#060d1a",       // Deep midnight sapphire ocean
    landColor: "#7eaad6",        // Silvery steel-blue continents
    atmosphereColor: "#38bdf8",  // Celestial ice-blue atmospheric glow
    ambientColor: "#0f172a",     // Low-level ambient
    fillLightColor: "#38bdf8",   // Soft cool fill
  },
} as const;

const BUMP_SCALE = 0.09;
const ROUGHNESS = 0.80;
const METALNESS = 0.0;

// ── Soft Ethereal Atmospheric Bloom Halo (Billboard behind globe) ────────────
function AtmosphereHalo({ color }: { color: string }) {
  const meshRef = useRef<THREE.Mesh>(null);

  // Keep halo plane facing the camera regardless of orbit interaction
  useFrame(({ camera }) => {
    if (meshRef.current) {
      meshRef.current.quaternion.copy(camera.quaternion);
    }
  });

  const uniforms = useMemo(
    () => ({
      uColor: { value: new THREE.Color(color) },
    }),
    [color]
  );

  return (
    <mesh ref={meshRef} position={[0, 0, -0.06]}>
      <planeGeometry args={[6.0, 6.0]} />
      <shaderMaterial
        vertexShader={`
          varying vec2 vUv;
          void main() {
            vUv = uv;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
          }
        `}
        fragmentShader={`
          varying vec2 vUv;
          uniform vec3 uColor;

          void main() {
            vec2 pos = (vUv - 0.5) * 2.0;
            float dist = length(pos);

            // Globe radius is 2.0 / half-width 3.0 = 0.667
            float rInner = 0.655;
            float rOuter = 0.88;

            if (dist < rInner || dist > rOuter) {
              discard;
            }

            // Soft cubic fade from globe horizon outwards into deep space
            float t = (dist - rInner) / (rOuter - rInner);
            float glow = pow(1.0 - t, 2.6) * 0.40;

            gl_FragColor = vec4(uColor, glow);
          }
        `}
        transparent={true}
        blending={THREE.AdditiveBlending}
        depthWrite={false}
        uniforms={uniforms}
      />
    </mesh>
  );
}

// ── Fallback Sphere (rendered while texture loads) ───────────────────────────
function GlobeFallback({
  oceanColor,
  autoRotate,
  rotationSpeed,
}: {
  oceanColor: string;
  autoRotate: boolean;
  rotationSpeed: number;
}) {
  const globeRef = useRef<THREE.Mesh>(null);

  useFrame(() => {
    if (globeRef.current && autoRotate) {
      globeRef.current.rotation.y += rotationSpeed;
    }
  });

  return (
    <mesh ref={globeRef}>
      <sphereGeometry args={[2, 64, 64]} />
      <meshStandardMaterial
        color={oceanColor}
        roughness={ROUGHNESS}
        metalness={METALNESS}
      />
    </mesh>
  );
}

// ── Main Textured Globe Mesh ────────────────────────────────────────────────
interface GlobeMeshProps {
  mode: "monochrome" | "default";
  bumpMapUrl: string;
  waterMapUrl: string;
  autoRotate: boolean;
  rotationSpeed: number;
}

function GlobeMesh({
  mode,
  bumpMapUrl,
  waterMapUrl,
  autoRotate,
  rotationSpeed,
}: GlobeMeshProps) {
  const globeRef = useRef<THREE.Mesh>(null);

  // Load elevation bump map + water/land mask texture
  const [bumpMap, waterMap] = useLoader(THREE.TextureLoader, [
    bumpMapUrl,
    waterMapUrl,
  ]);

  useFrame(() => {
    if (globeRef.current && autoRotate) {
      globeRef.current.rotation.y += rotationSpeed;
    }
  });

  const theme = THEMES[mode] || THEMES.monochrome;

  const customMaterial = useMemo(() => {
    const mat = new THREE.MeshStandardMaterial({
      roughness: ROUGHNESS,
      metalness: METALNESS,
      bumpMap,
      bumpScale: BUMP_SCALE,
    });

    mat.customProgramCacheKey = () => `globe2-aesthetic-${mode}`;

    mat.onBeforeCompile = (shader) => {
      shader.uniforms.uOceanColor = { value: new THREE.Color(theme.oceanColor) };
      shader.uniforms.uLandColor = { value: new THREE.Color(theme.landColor) };
      shader.uniforms.uAtmosphereColor = { value: new THREE.Color(theme.atmosphereColor) };
      shader.uniforms.uWaterMap = { value: waterMap };

      shader.fragmentShader =
        `
        uniform vec3 uOceanColor;
        uniform vec3 uLandColor;
        uniform vec3 uAtmosphereColor;
        uniform sampler2D uWaterMap;
      ` + shader.fragmentShader;

      shader.fragmentShader = shader.fragmentShader.replace(
        "#include <map_fragment>",
        `
        #include <map_fragment>
        #ifdef USE_BUMPMAP
          // 1. Water vs Land separation from 2K specular mask
          float waterVal = texture2D(uWaterMap, vBumpMapUv).r;
          float landMask = 1.0 - smoothstep(0.40, 0.60, waterVal);

          // 2. Tactile mountain & terrain relief from 4K heightmap
          float elevVal = texture2D(bumpMap, vBumpMapUv).r;
          // Valley lowlands to snow-peaked crests
          vec3 styledLand = mix(uLandColor * 0.88, vec3(1.0), smoothstep(0.03, 0.60, elevVal) * 0.65);

          // 3. High-contrast continental landmasses against deep obsidian ocean
          diffuseColor.rgb = mix(uOceanColor, styledLand, landMask);
        #endif
        `
      );

      // 4. Eliminate harsh pinpoint specular glare spots
      shader.fragmentShader = shader.fragmentShader.replace(
        "vec3 totalSpecular = reflectedLight.directSpecular + reflectedLight.indirectSpecular;",
        "vec3 totalSpecular = vec3(0.0);"
      );
    };

    return mat;
  }, [bumpMap, waterMap, mode, theme]);

  return (
    <mesh ref={globeRef} material={customMaterial}>
      <sphereGeometry args={[2, 64, 64]} />
    </mesh>
  );
}

// ── Exported Component ──────────────────────────────────────────────────────
export function Globe2({
  mode = "monochrome",
  bumpMapUrl = "/earth-bump.png",
  waterMapUrl = "/earth-specular.jpg",
  autoRotate = true,
  rotationSpeed = 0.0015,
  interactive = true,
  enableZoom = true,
  minDistance = 3.5,
  maxDistance = 10,
  fov = 45,
  className = "",
  style,
}: Globe2Props) {
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const theme = THEMES[mode] || THEMES.monochrome;

  if (!mounted) {
    return (
      <div
        className={cn(
          "relative w-full h-full min-h-[380px] flex items-center justify-center select-none",
          className
        )}
        style={style}
      >
        <div className="w-48 h-48 rounded-full bg-slate-900/60 animate-pulse border border-white/10" />
      </div>
    );
  }

  return (
    <div
      className={cn(
        "relative w-full h-full min-h-[380px] flex items-center justify-center select-none",
        className
      )}
      style={style}
    >
      <Canvas
        camera={{ position: [0, 0, 5.8], fov }}
        gl={{ antialias: true, alpha: true }}
        style={{ pointerEvents: interactive ? "auto" : "none" }}
      >
        {/* Subtle, calibrated ambient fill preserving deep obsidian blacks */}
        <ambientLight intensity={0.15} color={theme.ambientColor} />

        {/* Primary warm/pure key sunlight illuminating continental terrain from a natural angle */}
        <directionalLight
          position={[5, 3, 4]}
          intensity={2.6}
          color="#ffffff"
        />

        {/* Soft secondary fill from the opposite side */}
        <directionalLight
          position={[-5, -1, -2]}
          intensity={0.25}
          color={theme.fillLightColor}
        />

        {/* Soft ethereal atmospheric halo blooming behind the globe */}
        <AtmosphereHalo color={theme.atmosphereColor} />

        {/* Textured globe with seamless suspense fallback */}
        <Suspense
          fallback={
            <GlobeFallback
              oceanColor={theme.oceanColor}
              autoRotate={autoRotate}
              rotationSpeed={rotationSpeed}
            />
          }
        >
          <GlobeMesh
            mode={mode}
            bumpMapUrl={bumpMapUrl}
            waterMapUrl={waterMapUrl}
            autoRotate={autoRotate}
            rotationSpeed={rotationSpeed}
          />
        </Suspense>

        {/* Orbit Controls with physical momentum damping */}
        {interactive && (
          <OrbitControls
            enableZoom={enableZoom}
            enablePan={false}
            enableDamping={true}
            dampingFactor={0.05}
            minDistance={minDistance}
            maxDistance={maxDistance}
            rotateSpeed={0.8}
          />
        )}
      </Canvas>
    </div>
  );
}

export default Globe2;
